create extension if not exists pgcrypto;
create schema if not exists private;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id) on delete set null,name text not null check(char_length(name) between 1 and 160),short_description text,full_description text,category_id uuid references public.categories(id) on delete set null,category_name text,price_pkr numeric(12,2) not null default 0 check(price_pkr>=0),discount_price_pkr numeric(12,2),main_image_url text,logo_url text,visit_url text,buy_url text,affiliate_url text,download_url text,tags text[] not null default '{}',featured boolean not null default false,published boolean not null default false,status text not null default 'pending' check(status in('pending','approved','rejected')),seo_title text,seo_description text,seo_keywords text,reviewed_at timestamptz,reviewed_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text,public_url text not null,alt_text text,sort_order integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,subject text not null check(char_length(subject) between 1 and 160),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.message_replies(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 5000),read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.message_initial(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,customer_name text not null,customer_email text not null,customer_phone text,items jsonb not null default '[]',amount_pkr numeric(12,2) not null default 0,status text not null default 'pending' check(status in('pending','processing','completed','cancelled')),payment_status text not null default 'not_configured',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_settings(id boolean primary key default true check(id=true),site_title text not null default 'Waris Ali Digital Hub',meta_description text not null default 'Useful Digital Tools, Apps & Websites — All in One Place',keywords text not null default 'digital tools, AI tools, apps, websites, games',announcement text,updated_at timestamptz not null default now());
create table if not exists public.page_views(id bigint generated by default as identity primary key,path text not null,user_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
insert into public.site_settings(id) values(true) on conflict(id) do nothing;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin') $$;
revoke all on function private.is_admin() from public,anon; grant execute on function private.is_admin() to authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,avatar_url,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url',case when lower(coalesce(new.email,''))='warisalidigitalsolutions@gmail.com' then 'admin' else 'user' end) on conflict(id) do update set full_name=excluded.full_name,avatar_url=excluded.avatar_url; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.sync_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','products','categories','messages','orders','site_settings'] loop execute format('drop trigger if exists %I_updated_at on public.%I',t,t); execute format('create trigger %I_updated_at before update on public.%I for each row execute procedure public.sync_updated_at()',t,t); end loop; end $$;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.messages enable row level security; alter table public.message_replies enable row level security; alter table public.message_initial enable row level security; alter table public.orders enable row level security; alter table public.site_settings enable row level security; alter table public.page_views enable row level security;
revoke all on public.profiles,public.categories,public.products,public.product_images,public.messages,public.message_replies,public.message_initial,public.orders,public.site_settings,public.page_views from anon; grant select on public.categories,public.products,public.product_images,public.site_settings to anon; grant select,insert,update,delete on public.profiles,public.products,public.product_images,public.messages,public.message_replies,public.message_initial,public.orders,public.categories,public.site_settings,public.page_views to authenticated; grant insert on public.page_views to anon;
drop policy if exists "profile read" on public.profiles; create policy "profile read" on public.profiles for select to authenticated using(id=(select auth.uid()) or (select private.is_admin()));
drop policy if exists "profile update" on public.profiles; create policy "profile update" on public.profiles for update to authenticated using(id=(select auth.uid()) or (select private.is_admin())) with check(id=(select auth.uid()) or (select private.is_admin()));
drop policy if exists "category read" on public.categories; create policy "category read" on public.categories for select to anon,authenticated using(true); drop policy if exists "category admin insert" on public.categories; create policy "category admin insert" on public.categories for insert to authenticated with check((select private.is_admin())); drop policy if exists "category admin update" on public.categories; create policy "category admin update" on public.categories for update to authenticated using((select private.is_admin())) with check((select private.is_admin())); drop policy if exists "category admin delete" on public.categories; create policy "category admin delete" on public.categories for delete to authenticated using((select private.is_admin()));
drop policy if exists "product read" on public.products; create policy "product read" on public.products for select to anon,authenticated using((status='approved' and published=true) or owner_id=(select auth.uid()) or (select private.is_admin()));
drop policy if exists "product user insert" on public.products; create policy "product user insert" on public.products for insert to authenticated with check(owner_id=(select auth.uid()) and status='pending' and published=false and featured=false);
drop policy if exists "product owner update" on public.products; create policy "product owner update" on public.products for update to authenticated using(owner_id=(select auth.uid()) and status in('pending','rejected')) with check(owner_id=(select auth.uid()) and status='pending' and published=false and featured=false);
drop policy if exists "product admin update" on public.products; create policy "product admin update" on public.products for update to authenticated using((select private.is_admin())) with check((select private.is_admin()));
drop policy if exists "product owner delete" on public.products; create policy "product owner delete" on public.products for delete to authenticated using(owner_id=(select auth.uid()) and status<>'approved'); drop policy if exists "product admin delete" on public.products; create policy "product admin delete" on public.products for delete to authenticated using((select private.is_admin()));
drop policy if exists "product images read" on public.product_images; create policy "product images read" on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and ((p.status='approved' and p.published=true) or p.owner_id=(select auth.uid()) or (select private.is_admin()))));
drop policy if exists "product images write" on public.product_images; create policy "product images write" on public.product_images for insert to authenticated with check(exists(select 1 from public.products p where p.id=product_id and (p.owner_id=(select auth.uid()) or (select private.is_admin())))); create policy "product images update" on public.product_images for update to authenticated using(exists(select 1 from public.products p where p.id=product_id and (p.owner_id=(select auth.uid()) or (select private.is_admin())))) with check(exists(select 1 from public.products p where p.id=product_id and (p.owner_id=(select auth.uid()) or (select private.is_admin())))); create policy "product images delete" on public.product_images for delete to authenticated using(exists(select 1 from public.products p where p.id=product_id and (p.owner_id=(select auth.uid()) or (select private.is_admin()))));
drop policy if exists "messages read" on public.messages; create policy "messages read" on public.messages for select to authenticated using(user_id=(select auth.uid()) or (select private.is_admin())); drop policy if exists "messages insert" on public.messages; create policy "messages insert" on public.messages for insert to authenticated with check(user_id=(select auth.uid())); drop policy if exists "messages update" on public.messages; create policy "messages update" on public.messages for update to authenticated using((select private.is_admin())) with check((select private.is_admin())); drop policy if exists "messages delete" on public.messages for delete to authenticated using(user_id=(select auth.uid()) or (select private.is_admin()));
create policy "initial read" on public.message_initial for select to authenticated using(sender_id=(select auth.uid()) or (select private.is_admin())); create policy "initial insert" on public.message_initial for insert to authenticated with check(sender_id=(select auth.uid()));
create policy "reply read" on public.message_replies for select to authenticated using(sender_id=(select auth.uid()) or (select private.is_admin()) or exists(select 1 from public.messages m where m.id=message_id and m.user_id=(select auth.uid()))); drop policy if exists "reply insert" on public.message_replies; create policy "reply insert" on public.message_replies for insert to authenticated with check(sender_id=(select auth.uid()) and ((select private.is_admin()) or exists(select 1 from public.messages m where m.id=message_id and m.user_id=(select auth.uid())))); drop policy if exists "reply update" on public.message_replies; create policy "reply update" on public.message_replies for update to authenticated using(sender_id=(select auth.uid()) or (select private.is_admin())) with check(sender_id=(select auth.uid()) or (select private.is_admin())); drop policy if exists "reply delete" on public.message_replies; create policy "reply delete" on public.message_replies for delete to authenticated using(sender_id=(select auth.uid()) or (select private.is_admin()));
create policy "orders read" on public.orders for select to authenticated using(user_id=(select auth.uid()) or (select private.is_admin())); create policy "orders insert" on public.orders for insert to authenticated with check(user_id=(select auth.uid())); create policy "orders admin update" on public.orders for update to authenticated using((select private.is_admin())) with check((select private.is_admin())); create policy "orders admin delete" on public.orders for delete to authenticated using((select private.is_admin()));
create policy "settings read" on public.site_settings for select to anon,authenticated using(true); create policy "settings admin update" on public.site_settings for update to authenticated using((select private.is_admin())) with check((select private.is_admin()));
create policy "views insert" on public.page_views for insert to anon,authenticated with check(user_id is null or user_id=(select auth.uid())); create policy "views admin read" on public.page_views for select to authenticated using((select private.is_admin()));
insert into public.categories(name,slug) values('AI Tools','ai-tools'),('Apps','apps'),('Websites','websites'),('Games','games'),('Digital Products','digital-products'),('Services','services'),('Special Offers','special-offers') on conflict(slug) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('media','media',true,8388608,array['image/jpeg','image/png','image/webp','image/gif','image/svg+xml']) on conflict(id) do update set public=true,file_size_limit=8388608;
drop policy if exists "media read" on storage.objects; create policy "media read" on storage.objects for select to anon,authenticated using(bucket_id='media');
drop policy if exists "media insert" on storage.objects; create policy "media insert" on storage.objects for insert to authenticated with check(bucket_id='media' and ((storage.foldername(name))[1]=(select auth.uid()::text) or (select private.is_admin())));
drop policy if exists "media update" on storage.objects; create policy "media update" on storage.objects for update to authenticated using(bucket_id='media' and (owner_id=(select auth.uid()) or (select private.is_admin()))) with check(bucket_id='media' and (owner_id=(select auth.uid()) or (select private.is_admin())));
drop policy if exists "media delete" on storage.objects; create policy "media delete" on storage.objects for delete to authenticated using(bucket_id='media' and (owner_id=(select auth.uid()) or (select private.is_admin())));
create index if not exists products_status_published_idx on public.products(status,published); create index if not exists products_owner_idx on public.products(owner_id); create index if not exists product_images_product_idx on public.product_images(product_id,sort_order); create index if not exists messages_user_idx on public.messages(user_id);
